option.value:
/*
  Markdown → DOCX generator for LakbayLaya manual.

  Why this script exists:
  - The installed `md-to-docx` package is a library (no CLI shim on Windows).
  - This script converts the Markdown file into a .docx using the library.

  Output:
  - LAKBAYLAYA_USER_MANUAL.docx (in project root)

  Usage (PowerShell):
    node .\tools\md_to_docx.js
*/

const fs = require("fs");
const path = require("path");

function requireMdToDocx() {
  try {
    return require("md-to-docx");
  } catch (_) {
    // Fallback: global npm install location (Windows)
    const globalPath = path.join(
      process.env.APPDATA || "",
      "npm",
      "node_modules",
      "md-to-docx"
    );
    return require(globalPath);
  }
}

async function main() {
  const projectRoot = path.resolve(__dirname, "..");
  const inputPath = path.join(projectRoot, "LAKBAYLAYA_USER_MANUAL.md");
  const outputPath = path.join(projectRoot, "LAKBAYLAYA_USER_MANUAL.docx");

  if (!fs.existsSync(inputPath)) {
    throw new Error(`Input Markdown not found: ${inputPath}`);
  }

  const markdown = fs.readFileSync(inputPath, "utf8");

  // md-to-docx exports conversion utilities via its dist entry.
  // We'll try a few common export names to remain compatible across versions.
  const m2d = requireMdToDocx();

  const toDocx = m2d.toDocx || m2d.default?.toDocx || m2d.default || m2d;
  if (typeof toDocx !== "function") {
    throw new Error(
      "md-to-docx does not expose a toDocx() function as expected. " +
        "Installed version may have changed exports."
    );
  }

  // Many examples show: markdown -> mdast (remark-parse) -> toDocx(mdast)
  // We'll follow that approach.
  const { unified } = require("unified");
  // remark-* packages are ESM in modern versions. Use dynamic import to load them reliably.
  const remarkParse = (await import("remark-parse")).default;
  const remarkGfm = (await import("remark-gfm")).default;

  const mdast = unified().use(remarkParse).use(remarkGfm).parse(markdown);

  const result = await toDocx(mdast);

  // The library may return a Buffer, Uint8Array, or Blob-like object.
  // Normalize to Buffer for file write.
  let buffer;
  if (Buffer.isBuffer(result)) {
    buffer = result;
  } else if (result instanceof Uint8Array) {
    buffer = Buffer.from(result);
  } else if (result && typeof result.arrayBuffer === "function") {
    buffer = Buffer.from(await result.arrayBuffer());
  } else {
    throw new Error(
      `Unsupported toDocx() return type: ${Object.prototype.toString.call(result)}`
    );
  }

  fs.writeFileSync(outputPath, buffer);
  process.stdout.write(`DOCX created: ${outputPath}\n`);
}

main().catch((err) => {
  console.error("Failed to generate DOCX:\n", err);
  process.exit(1);
});
